using Azure.AI.OpenAI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

/// <summary>
/// Shared setup for evaluation scenarios: configures the chat client,
/// reporting, and evaluators for telemetry, quality, and compare modes.
/// </summary>
internal static class EvalSetup
{
    private static readonly string Endpoint =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
        ?? "https://localhost";

    private static readonly string ModelDeployment =
        Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
        ?? "gpt-4o-mini";

    public static IChatClient CreateChatClient()
    {
        var azureClient = new AzureOpenAIClient(
            new Uri(Endpoint),
            new Azure.AzureKeyCredential(
                Environment.GetEnvironmentVariable("AZURE_OPENAI_KEY") ?? ""));

        return azureClient
            .GetChatClient(ModelDeployment)
            .AsIChatClient();
    }

    public static ReportingConfiguration CreateReportingConfig(string scenarioName)
    {
        var storagePath = Path.Combine("TestResults", "Evals", scenarioName);

        return new ReportingConfiguration(
            storageRootPath: storagePath,
            evaluators: GetEvaluators(),
            chatConfiguration: CreateChatConfiguration());
    }

    public static ChatConfiguration CreateChatConfiguration()
    {
        return new ChatConfiguration(chatClientFactory: () => CreateChatClient());
    }

    public static IList<IEvaluator> GetEvaluators()
    {
        return
        [
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        ];
    }
}

using System.Diagnostics;
using Microsoft.Extensions.AI;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that agent interactions produce correct
/// OpenTelemetry spans and stay within latency thresholds.
/// </summary>
[TestClass]
public class TelemetryMode
{
    private static readonly ActivitySource Source = new("MyApp.Evals.Telemetry");

    [TestMethod]
    public async Task Agent_ProducesChatCompletionSpan()
    {
        var activities = new List<Activity>();
        using var listener = new ActivityListener
        {
            ShouldListenTo = s => s.Name.Contains("OpenAI") || s.Name.Contains("MyApp"),
            Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllDataAndRecorded,
            ActivityStopped = a => activities.Add(a),
        };
        ActivitySource.AddActivityListener(listener);

        var client = EvalSetup.CreateChatClient();

        using var activity = Source.StartActivity("eval.telemetry");
        var response = await client.GetResponseAsync("What is 2+2?");

        Assert.IsNotNull(response);
        Assert.IsTrue(
            activities.Any(a => a.OperationName.Contains("chat", StringComparison.OrdinalIgnoreCase)),
            "Expected a chat completion span in the telemetry trace.");
    }

    [TestMethod]
    public async Task Agent_RespondsWithinLatencyThreshold()
    {
        var client = EvalSetup.CreateChatClient();
        var sw = Stopwatch.StartNew();

        await client.GetResponseAsync("Say hello.");

        sw.Stop();
        Assert.IsTrue(
            sw.ElapsedMilliseconds < 10_000,
            $"Response took {sw.ElapsedMilliseconds}ms, exceeding the 10000ms threshold.");
    }
}

using Microsoft.Extensions.AI;
