using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Quality mode: runs LLM-as-judge evaluations scoring relevance,
/// coherence, fluency, and groundedness on agent responses.
/// </summary>
[TestClass]
public class QualityMode
{
    private const double Threshold = 3.0;

    [TestMethod]
    public async Task CoachResponse_MeetsQualityThresholds()
    {
        var client = EvalSetup.CreateChatClient();

        var userMessage = "Give me a concise tip for improving my morning routine.";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, userMessage),
        };

        var response = await client.GetResponseAsync(messages);
        var assistantMessage = response.Text ?? string.Empty;

        // Run quality evaluators
        var evaluators = EvalSetup.GetEvaluators();
        var chatConfig = EvalSetup.CreateChatConfiguration();

        var context = new EvaluationContext
        {
            Messages = messages,
            ModelResponse = new ChatMessage(ChatRole.Assistant, assistantMessage),
        };

        foreach (var evaluator in evaluators)
        {
            await evaluator.InitializeAsync(chatConfig);
            var result = await evaluator.EvaluateAsync(context);

            foreach (var metric in result.Metrics)
            {
                if (metric.Value is NumericMetricValue numericValue)
                {
                    Assert.IsTrue(
                        numericValue.Value >= Threshold,
                        $"{metric.Key} scored {numericValue.Value}, below threshold {Threshold}.");
                }
            }
        }
    }

    [TestMethod]
    public async Task CoachResponse_IsRelevantToQuery()
    {
        var client = EvalSetup.CreateChatClient();

        var userMessage = "How can I stay focused while working from home?";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, userMessage),
        };

        var response = await client.GetResponseAsync(messages);
        var assistantMessage = response.Text ?? string.Empty;

        var evaluator = new RelevanceEvaluator();
        var chatConfig = EvalSetup.CreateChatConfiguration();
        await evaluator.InitializeAsync(chatConfig);

        var context = new EvaluationContext
        {
            Messages = messages,
            ModelResponse = new ChatMessage(ChatRole.Assistant, assistantMessage),
        };

        var result = await evaluator.EvaluateAsync(context);

        foreach (var metric in result.Metrics)
        {
            if (metric.Value is NumericMetricValue numericValue)
            {
                Assert.IsTrue(
                    numericValue.Value >= Threshold,
                    $"Relevance scored {numericValue.Value}, below threshold {Threshold}.");
            }
        }
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Compare mode: runs the same scenario against baseline and candidate
/// configurations, then asserts that the candidate does not regress.
/// </summary>
[TestClass]
public class CompareMode
{
    [TestMethod]
    public async Task Candidate_DoesNotRegress_VsBaseline()
    {
        var prompt = "Suggest one strategy for managing meeting overload.";

        // Baseline run
        var baselineScore = await RunAndScore(prompt, tag: "baseline");

        // Candidate run (same model here; swap deployment via env var for real comparisons)
        var candidateScore = await RunAndScore(prompt, tag: "candidate");

        var delta = candidateScore - baselineScore;
        Assert.IsTrue(
            delta >= -0.5,
            $"Candidate regressed by {delta:F2} points compared to baseline.");
    }

    [TestMethod]
    public async Task Responses_HaveSufficientSimilarity()
    {
        var prompt = "What is a good way to end a workday?";

        var baselineResponse = await GetResponse(prompt);
        var candidateResponse = await GetResponse(prompt);

        // Simple token-overlap similarity as a proxy
        var similarity = ComputeTokenOverlap(baselineResponse, candidateResponse);
        Assert.IsTrue(
            similarity >= 0.1,
            $"Response similarity {similarity:F2} is below the 0.1 threshold.");
    }

    private static async Task<double> RunAndScore(string prompt, string tag)
    {
        var client = EvalSetup.CreateChatClient();
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, prompt),
        };

        var response = await client.GetResponseAsync(messages);
        var assistantMessage = response.Text ?? string.Empty;

        var evaluator = new RelevanceEvaluator();
        var chatConfig = EvalSetup.CreateChatConfiguration();
        await evaluator.InitializeAsync(chatConfig);

        var context = new EvaluationContext
        {
            Messages = messages,
            ModelResponse = new ChatMessage(ChatRole.Assistant, assistantMessage),
        };

        var result = await evaluator.EvaluateAsync(context);

        foreach (var metric in result.Metrics)
        {
            if (metric.Value is NumericMetricValue numericValue)
            {
                return numericValue.Value;
            }
        }

        return 0.0;
    }

    private static async Task<string> GetResponse(string prompt)
    {
        var client = EvalSetup.CreateChatClient();
        var response = await client.GetResponseAsync(prompt);
        return response.Text ?? string.Empty;
    }

    private static double ComputeTokenOverlap(string a, string b)
    {
        var tokensA = a.Split(' ', StringSplitOptions.RemoveEmptyEntries)
            .Select(t => t.ToLowerInvariant()).ToHashSet();
        var tokensB = b.Split(' ', StringSplitOptions.RemoveEmptyEntries)
            .Select(t => t.ToLowerInvariant()).ToHashSet();

        if (tokensA.Count == 0 || tokensB.Count == 0) return 0.0;

        var intersection = tokensA.Intersect(tokensB).Count();
        var union = tokensA.Union(tokensB).Count();
        return (double)intersection / union;
    }
}

